    "grammarFocus": "形容词并列修饰与祈使句 (Sit down / Look at...)",
    "grammarNotes": [
      "There is / There are 引导的倒装存在句简介：There is an ice cream man.",
      "and 连接两个并列形容词：tired and thirsty（又累又渴）。"
    ],
